import React, { useMemo } from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  random,
  spring,
} from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type FireworksProps = Record<string, any>;

interface Particle {
  id: number;
  angle: number;
  speed: number;
  color: string;
  size: number;
  decay: number;
}

interface Explosion {
  id: number;
  x: number;
  y: number;
  startFrame: number;
  particles: Particle[];
}

const COLORS = [
  "#FF004D", // Red
  "#00FF66", // Green
  "#55DDFF", // Blue
  "#FFD700", // Gold
  "#FF6600", // Orange
  "#CC33FF", // Purple
];

const Fireworks: React.FC<FireworksProps> = ({
  backgroundColor = "#0a0a0a",
  transparentBackground = false,
  durationInSeconds = 5,
  text = "Hi baby!",
  textColor = "#FFFF00",
  textSize = 120,
  explosionCount = 8,
  particlesPerExplosion = 80,
}) => {
  useFontLoader(["Pacifico"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Generate deterministic fireworks data
  const explosions: Explosion[] = useMemo(() => {
    const generatedExplosions: Explosion[] = [];

    for (let i = 0; i < explosionCount; i++) {
      const seed = `explosion-${i}`;
      // Random start frame (spread across the duration, minus some buffer at end)
      const startFrame = Math.floor(random(seed + "time") * (durationInSeconds * fps - 30));
      
      // Random position (keep away from extreme edges)
      const x = width * 0.1 + random(seed + "x") * width * 0.8;
      const y = height * 0.1 + random(seed + "y") * height * 0.6; // Keep mostly top/middle
      
      const particles: Particle[] = [];
      const explosionColor = COLORS[Math.floor(random(seed + "color") * COLORS.length)];

      for (let j = 0; j < particlesPerExplosion; j++) {
        const pSeed = `${seed}-p-${j}`;
        const angle = random(pSeed + "angle") * Math.PI * 2;
        const speed = 2 + random(pSeed + "speed") * 10; // Velocity
        const size = 2 + random(pSeed + "size") * 4;
        const decay = 0.92 + random(pSeed + "decay") * 0.04; // Friction/Decay factor

        particles.push({
          id: j,
          angle,
          speed,
          color: explosionColor,
          size,
          decay,
        });
      }

      generatedExplosions.push({
        id: i,
        x,
        y,
        startFrame,
        particles,
      });
    }
    
    // Sort by startFrame so rendering order is consistent
    return generatedExplosions.sort((a, b) => a.startFrame - b.startFrame);
  }, [explosionCount, particlesPerExplosion, durationInSeconds, fps, width, height]);

  // Text Animation
  const textOpacity = interpolate(frame, [0, 30], [0, 1], {
    extrapolateRight: "clamp",
  });
  
  const textScale = spring({
    frame,
    fps,
    config: { damping: 12 },
    from: 0.5,
    to: 1,
  });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      
      {/* Background Text Layer */}
      <AbsoluteFill
        style={{
          justifyContent: "center",
          alignItems: "center",
          zIndex: 1,
        }}
      >
        <h1
          style={{
            fontFamily: "Pacifico",
            fontSize: textSize,
            color: textColor,
            opacity: textOpacity,
            transform: `scale(${textScale})`,
            margin: 0,
            textAlign: "center",
            textShadow: "0 4px 10px rgba(0,0,0,0.3)",
          }}
        >
          {text}
        </h1>
      </AbsoluteFill>

      {/* Fireworks Layer */}
      <AbsoluteFill style={{ zIndex: 2, pointerEvents: "none" }}>
        {explosions.map((explosion) => {
          const time = frame - explosion.startFrame;
          
          // Don't render if explosion hasn't started or has effectively ended
          if (time < 0 || time > fps * 2) return null;

          return (
            <React.Fragment key={explosion.id}>
              {explosion.particles.map((p) => {
                // Physics Calculations
                // x = v0 * t * cos(theta) * friction^t
                // y = v0 * t * sin(theta) * friction^t + 0.5 * g * t^2
                
                // Using a simplified physics model for visual effect:
                // Apply friction to velocity over time
                const effectiveSpeed = p.speed * Math.pow(p.decay, time);
                
                // Calculate distance traveled based on decaying speed
                // Sum of geometric series: S_n = a(1-r^n)/(1-r) roughly
                const distance = (p.speed * (1 - Math.pow(p.decay, time))) / (1 - p.decay);
                
                const x = explosion.x + Math.cos(p.angle) * distance;
                const gravity = 0.5;
                const y = explosion.y + Math.sin(p.angle) * distance + (0.5 * gravity * Math.pow(time, 2));

                const opacity = interpolate(
                  time,
                  [0, 10, 40, 60],
                  [1, 1, 0.5, 0],
                  { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
                );

                if (opacity <= 0) return null;

                return (
                  <div
                    key={p.id}
                    style={{
                      position: "absolute",
                      left: x,
                      top: y,
                      width: p.size,
                      height: p.size,
                      backgroundColor: p.color,
                      borderRadius: "50%",
                      opacity,
                      transform: "translate(-50%, -50%)",
                      boxShadow: `0 0 ${p.size * 2}px ${p.color}`,
                    }}
                  />
                );
              })}
            </React.Fragment>
          );
        })}
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default Fireworks;